import{_ as t,o as a,c as i,ae as n}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"ADR 027: LangSmith Tracing for AI Observability","description":"","frontmatter":{},"headers":[],"relativePath":"adr/027-langsmith-tracing-integration.md","filePath":"adr/027-langsmith-tracing-integration.md"}'),o={name:"adr/027-langsmith-tracing-integration.md"};function r(s,e,l,c,d,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-027-langsmith-tracing-for-ai-observability" tabindex="-1">ADR 027: LangSmith Tracing for AI Observability <a class="header-anchor" href="#adr-027-langsmith-tracing-for-ai-observability" aria-label="Permalink to &quot;ADR 027: LangSmith Tracing for AI Observability&quot;">​</a></h1><ul><li>Status: accepted</li><li>Deciders: Elena, Antigravity</li><li>Date: 2026-03-04</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As the project transitioned from a monolithic local AI inference (Ollama) to a Cloud-Native architecture using <strong>Google Genkit</strong> and <strong>Gemini 2.5 Flash</strong>, the need for robust observability of AI interactions became critical.</p><p>While environment variables like <code>LANGCHAIN_TRACING_V2</code> were initially set, Genkit (unlike LangChain) does not natively support automatic tracing to LangSmith. This lack of visibility made it difficult to debug prompt performance, especially for complex requirements like multi-year experience or insurance certifications.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We decided to integrate the <strong>LangSmith SDK</strong> (<code>langsmith</code>) into the backend and manually instrument the AI service methods.</p><ol><li><strong>Library</strong>: Added <code>@langchain/langsmith</code> as a backend dependency.</li><li><strong>Instrumentation</strong>: Wrapped core methods in <code>GeminiGenkitService</code> (<code>analyze</code>, <code>compareProposal</code>, <code>compareBatch</code>) using the <code>traceable</code> function.</li><li><strong>Naming Convention</strong>: Standardized trace names (e.g., <code>analyze_tender</code>, <code>compare_proposal</code>) to improve dashboard searchability.</li><li><strong>Configuration</strong>: Continued using standard <code>LANGCHAIN_*</code> environment variables for authentication and project routing.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Full Traceability</strong>: Every AI generation now logs input/output schemas, system prompts, and full context to the LangSmith dashboard.</li><li><strong>Prompt Optimization</strong>: Real-world traces allowed for the refinement of the &quot;Senior Evaluator&quot; prompt, specifically improving the extraction of numerical experience requirements.</li><li><strong>Debugging</strong>: Production errors or unexpected AI responses can now be audited post-execution.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Manual Maintenance</strong>: Any new AI methods must be manually wrapped with <code>traceable</code>.</li><li><strong>Dependency</strong>: Adds a small dependency on the LangChain ecosystem within a Genkit project.</li></ul>',13)])])}const u=t(o,[["render",r]]);export{m as __pageData,u as default};
